In ui.html, add a post-processing step at the end of parseStops(). After positions are resolved, map the result through `premulStops(list)` and return that. Work segment by segment in premultiplied space:

```js
function premulStops(st) { // st: [{position, color:{r,g,b,a}}], already sorted by position
  if (st.length < 2) return st;
  const out = [];
  const push = (pos, c) => {
    const p = out[out.length - 1];
    if (p && p.position === pos && p.color.r === c.r && p.color.g === c.g && p.color.b === c.b && p.color.a === c.a) return;
    out.push({ position: pos, color: { r: c.r, g: c.g, b: c.b, a: c.a } });
  };
  for (let i = 0; i < st.length - 1; i++) {
    let A = st[i].color, B = st[i + 1].color;
    const p0 = st[i].position, p1 = st[i + 1].position;
    // A fully transparent endpoint takes the other endpoint's rgb, for this segment only.
    if (A.a === 0 && B.a > 0) A = { r: B.r, g: B.g, b: B.b, a: 0 };
    if (B.a === 0 && A.a > 0) B = { r: A.r, g: A.g, b: A.b, a: 0 };
    push(p0, A);
    const rgbDiff = Math.max(Math.abs(A.r - B.r), Math.abs(A.g - B.g), Math.abs(A.b - B.b));
    // Partly transparent at both ends: straight and premultiplied lerp differ, so add premultiplied sub-samples.
    if (A.a > 0 && B.a > 0 && Math.abs(A.a - B.a) > 0.15 && rgbDiff > 0.08 && p1 > p0) {
      const N = 6;
      for (let k = 1; k < N; k++) {
        const t = k / N, a = A.a + (B.a - A.a) * t;
        const m = (x, y) => (x * A.a + (y * B.a - x * A.a) * t) / a;
        push(p0 + (p1 - p0) * t, { r: m(A.r, B.r), g: m(A.g, B.g), b: m(A.b, B.b), a });
      }
    }
    push(p1, B);
  }
  return out;
}
```

How the main cases come out:
- **A zero-alpha stop between two visible stops** becomes two coincident stops ({prev.rgb, 0} and {next.rgb, 0}), because each adjacent segment rewrites its own endpoint. `red, rgba(255,0,0,0) 50%, blue` becomes red→red0 @0.5, blue0 @0.5→blue, which matches Chrome's light blue at 75%.
- **A zero-alpha first or last stop** takes its single neighbour's rgb. `from-white to-transparent` becomes white→white0.
- **Runs of a=0 stops and zero-length hard-stop segments** keep their rgb. A segment that is invisible on both ends needs no fix, and dedup removes the redundant stops.

Keep it compatible with the separate oklab sub-sampling fix: do the colour-space sampling first, then the premultiplied pass, or merge both into one sampler that interpolates in premultiplied oklab.

No change to code.js is needed. Figma accepts coincident stop positions, and the plugin already emits them for conic hard stops. Stop count rises by at most 5 per partly transparent segment.

In ui.html parseStops(), after computing positions (just before the final map), fix up zero-alpha stops so that unpremultiplied interpolation (Figma) matches CSS premultiplied interpolation:

```js
// raw: [{color:{r,g,b,a}, pos}] with positions resolved
const out = [];
for (let i = 0; i < raw.length; i++) {
  const s = raw[i];
  if (s.color.a > 0.001) { out.push(s); continue; }
  // nearest neighbours with visible alpha on each side
  let L = null, R = null;
  for (let j = i - 1; j >= 0; j--) if (raw[j].color.a > 0.001) { L = raw[j]; break; }
  for (let j = i + 1; j < raw.length; j++) if (raw[j].color.a > 0.001) { R = raw[j]; break; }
  const rgbOf = (n) => ({ r: n.color.r, g: n.color.g, b: n.color.b, a: 0 });
  if (L && R && (L.color.r !== R.color.r || L.color.g !== R.color.g || L.color.b !== R.color.b)) {
    // fade out L's colour, then fade in R's colour: two stops at the same position
    out.push({ pos: s.pos, color: rgbOf(L) });
    out.push({ pos: s.pos, color: rgbOf(R) });
  } else if (L || R) {
    out.push({ pos: s.pos, color: rgbOf(L || R) });
  } else out.push(s); // all stops transparent: leave as is
}
// optional, for partially transparent neighbours (0<a<1 with different alpha):
// between consecutive stops A,B whose alphas differ and both > 0, insert ~4 extra
// stops at t=k/5 whose colour is premix = (A.rgb*A.a*(1-t) + B.rgb*B.a*t) / a_t,
// with a_t = A.a*(1-t) + B.a*t (premultiplied lerp, un-premultiplied for Figma).
return out.map((s) => ({ position: clamp01(s.pos), color: { r: s.color.r, g: s.color.g, b: s.color.b, a: s.color.a } }));
```

